require("dotenv").config();
const {
  Client, GatewayIntentBits, Partials, PermissionsBitField,
  ChannelType, EmbedBuilder, ActionRowBuilder, ButtonBuilder,
  ButtonStyle, SlashCommandBuilder, REST, Routes, Events,
  ActivityType
} = require("discord.js");
const fs = require("fs");

const TOKEN = process.env.TOKEN;
const CLIENT_ID = process.env.CLIENT_ID;
if (!TOKEN || !CLIENT_ID) throw new Error("TOKEN ve CLIENT_ID .env içinde olmalı.");

const DB_FILE = "./database.json";
const db = fs.existsSync(DB_FILE) ? JSON.parse(fs.readFileSync(DB_FILE, "utf8")) : {
  guilds: {}, users: {}
};
const save = () => fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2));

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds, GatewayIntentBits.GuildMembers,
    GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent,
    GatewayIntentBits.GuildModeration
  ],
  partials: [Partials.Channel, Partials.Message, Partials.User]
});

