function guildData(gid) {
  if (!db.guilds[gid]) db.guilds[gid] = {
    setup: false, roles: {}, channels: {},
    automod: { enabled: true, spam: true, links: false, badWords: true }
  };
  return db.guilds[gid];
}
function userData(gid, uid) {
  const k = `${gid}:${uid}`;
  if (!db.users[k]) db.users[k] = { xp: 0, level: 1, coins: 0, warnings: [], daily: 0, work: 0 };
  return db.users[k];
}
function embed(title, description) {
  return new EmbedBuilder().setTitle(title).setDescription(description)
    .setColor(0x5865F2).setTimestamp();
}
function isAdmin(i) {
  return i.guild.ownerId === i.user.id ||
    i.member.permissions.has(PermissionsBitField.Flags.Administrator) ||
    i.member.roles.cache.has(guildData(i.guild.id).roles.admin);
}
function isMod(i) {
  return isAdmin(i) ||
    i.member.permissions.has(PermissionsBitField.Flags.ModerateMembers) ||
    i.member.roles.cache.has(guildData(i.guild.id).roles.mod);
}
function isSupport(i) {
  return isAdmin(i) || isMod(i) ||
    i.member.roles.cache.has(guildData(i.guild.id).roles.support);
}
async function log(guild, channelKey, title, text) {
  const id = guildData(guild.id).channels[channelKey];
  const ch = id && guild.channels.cache.get(id);
  if (ch) await ch.send({ embeds: [embed(title, text)] }).catch(() => {});
}
function overwrites(guild, roles, type) {
  const everyone = guild.roles.everyone.id;
  const deny = { ViewChannel: false };
  const base = [{ id: everyone, deny: [PermissionsBitField.Flags.ViewChannel] }];
  if (type === "mod") {
    base.push({ id: roles.mod, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
    base.push({ id: roles.admin, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
  }
  if (type === "admin") {
    base.push({ id: roles.admin, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
  }
  if (type === "support") {
    base.push({ id: roles.support, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
    base.push({ id: roles.mod, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
    base.push({ id: roles.admin, allow: [PermissionsBitField.Flags.ViewChannel, PermissionsBitField.Flags.SendMessages] });
  }
  return base;
}

async function setup(guild) {
  if (!guild.members.me.permissions.has(PermissionsBitField.Flags.Administrator))
    throw new Error("Botun Administrator yetkisi olmalı.");

  const cfg = guildData(guild.id);
  const roles = {};

  // Rolleri oluştur ve hiyerarşiye göre sakla.
  for (const [emoji, name, color] of roleDefs) {
    let r = guild.roles.cache.find(x => x.name === `${emoji} ${name}`);
    if (!r) r = await guild.roles.create({ name: `${emoji} ${name}`, color, reason: "Full server setup" });
    roles[name] = r.id;
  }
  cfg.roles = {
    owner: roles["Sunucu Sahibi"], admin: roles["Yönetici"],
    headMod: roles["Baş Moderatör"], mod: roles["Moderatör"],
    trialMod: roles["Deneme Moderatör"], support: roles["Destek Sorumlusu"],
    event: roles["Etkinlik Sorumlusu"], bot: roles["Bot"],
    booster: roles["Booster"], vip: roles["VIP"], active: roles["Aktif Üye"],
    member: roles["Üye"]
  };

  // Bot rolünü yukarı taşımayı dene; Discord bot rolünü kendi rolünün üstüne çıkaramaz.
  const botMember = guild.members.me;
  const botRole = botMember.roles.botRole;
  if (botRole) {
    const maxPos = Math.max(1, guild.roles.cache.filter(r => r.editable && !r.managed).reduce((m, r) => Math.max(m, r.position), 1));
    await botRole.setPosition(Math.min(maxPos, guild.roles.highest.position - 1)).catch(() => {});
  }

  // Kanal oluşturma yardımcıları
  const getCat = async name => {
    let c = guild.channels.cache.find(x => x.type === ChannelType.GuildCategory && x.name === name);
    if (!c) c = await guild.channels.create({ name, type: ChannelType.GuildCategory });
    return c;
  };
  const getText = async (name, parent, opts = {}) => {
    let c = guild.channels.cache.find(x => x.type === ChannelType.GuildText && x.name === name);
    if (!c) c = await guild.channels.create({ name, type: ChannelType.GuildText, parent, ...opts });
    else if (c.parentId !== parent.id) await c.setParent(parent.id).catch(() => {});
    return c;
  };
  const getVoice = async (name, parent, opts = {}) => {
    let c = guild.channels.cache.find(x => x.type === ChannelType.GuildVoice && x.name === name);
    if (!c) c = await guild.channels.create({ name, type: ChannelType.GuildVoice, parent, ...opts });
    return c;
  };

  const channelMap = {};
  for (const [catName, chans] of categoryDefs) {
    const cat = await getCat(catName);
    let type = "public";
    if (catName === "🔐 YÖNETİM") type = "mod";
    for (const [name, kind] of chans) {
      const opts = type === "mod" ? { permissionOverwrites: overwrites(guild, cfg.roles, "mod") } : {};
      const c = kind === "text" ? await getText(name, cat, opts) : await getVoice(name, cat, opts);
      channelMap[name] = c.id;
    }
  }
  cfg.channels = {
    rules: channelMap["📜・kurallar"], announcements: channelMap["📢・duyurular"],
    info: channelMap["📋・bilgilendirme"], events: channelMap["🗓️・etkinlikler"],
    faq: channelMap["❓・sss"], general: channelMap["💬・genel"],
    commands: channelMap["🤖・bot-komutları"], media: channelMap["📸・medya"],
    games: channelMap["🎮・oyun"], suggestions: channelMap["💡・öneriler"],
    ticket: channelMap["🎫・ticket"], applications: channelMap["📮・başvuru"],
    support: channelMap["🤝・destek"], event: channelMap["🎉・etkinlik"],
    giveaway: channelMap["🏅・çekiliş"], winners: channelMap["🏆・kazananlar"],
    botlog: channelMap["📊・bot-log"], stats: channelMap["📈・istatistik"],
    logs: channelMap["📋・loglar"], modlog: channelMap["🛡️・mod-log"],
    automod: channelMap["🚨・automod-log"], staff: channelMap["👥・yetkili"],
    management: channelMap["🔒・yönetim"]
  };

  // Özel kanal izinleri
  const publicReadOnly = ["rules", "announcements", "info", "faq", "events", "winners"];
  for (const key of publicReadOnly) {
    const c = guild.channels.cache.get(cfg.channels[key]);
    if (c) await c.permissionOverwrites.edit(guild.roles.everyone, { SendMessages: false }).catch(() => {});
  }
  for (const key of ["logs", "modlog", "automod", "staff"]) {
    const c = guild.channels.cache.get(cfg.channels[key]);
    if (c) await c.permissionOverwrites.set(overwrites(guild, cfg.roles, "mod")).catch(() => {});
  }
  const adminOnly = guild.channels.cache.get(cfg.channels.management);
  if (adminOnly) await adminOnly.permissionOverwrites.set(overwrites(guild, cfg.roles, "admin")).catch(() => {});
  const ticket = guild.channels.cache.get(cfg.channels.ticket);
  if (ticket) await ticket.permissionOverwrites.edit(guild.roles.everyone, { ViewChannel: true, SendMessages: false }).catch(() => {});

  // Kurallar ve ticket paneli yalnızca ilk kurulumda/boş kanalda gönderilir.
  const rulesCh = guild.channels.cache.get(cfg.channels.rules);
  if (rulesCh && rulesCh.messages.cache.size === 0) await rulesCh.send({
    embeds: [embed("📜 Sunucu Kuralları",
      "1. Saygılı olun.\n2. Spam/reklam yapmayın.\n3. Taciz ve tehdit yasaktır.\n4. Yetkili kararlarına uyun.\n5. Discord Kuralları ve Topluluk Kuralları geçerlidir.")],
  });
  if (ticket && ticket.messages.cache.size === 0) {
    const row = new ActionRowBuilder().addComponents(
      new ButtonBuilder().setCustomId("ticket_create").setLabel("Ticket Aç").setEmoji("🎫").setStyle(ButtonStyle.Primary)
    );
    await ticket.send({ embeds: [embed("🎫 Destek Merkezi", "Destek almak için aşağıdaki butona bas.")], components: [row] });
  }
  cfg.setup = true; save(); return cfg;
}

