client.on(Events.VoiceStateUpdate, async (oldState, newState) => {
  const guild = newState.guild || oldState.guild;
  if (!guild) return;
  const cfg = ultraGuild(guild.id);
  if (!cfg.logs.voice) return;

  const member = newState.member || oldState.member;
  if (!member) return;

  if (!oldState.channelId && newState.channelId) {
    await ultraSendLog(
      guild,
      "VOICE",
      "🔊 Ses Kanalına Katıldı",
      `${member} → <#${newState.channelId}>`
    );
  } else if (oldState.channelId && !newState.channelId) {
    await ultraSendLog(
      guild,
      "VOICE",
      "🔇 Ses Kanalından Ayrıldı",
      `${member} ← <#${oldState.channelId}>`
    );
  } else if (oldState.channelId !== newState.channelId) {
    await ultraSendLog(
      guild,
      "VOICE",
      "🔄 Ses Kanalı Değişti",
      `${member}\n<#${oldState.channelId}> → <#${newState.channelId}>`
    );
  }
});

/*
  A second message listener performs only the ultra security checks and AFK
  handling. It does not replace the original message listener.
*/
client.on(Events.MessageCreate, async message => {
  try {
    if (!message.guild || message.author.bot) return;

    const blocked = await ultraSecurityCheck(message);
    if (blocked) return;

    const mine = getAFK(message.guild.id, message.author.id);
    if (mine) {
      clearAFK(message.guild.id, message.author.id);
      await message.reply({
        embeds: [embed("👋 AFK Kapatıldı", "Tekrar hoş geldin!")]
      }).catch(() => {});
    }

    for (const user of message.mentions.users.values()) {
      const afk = getAFK(message.guild.id, user.id);
      if (afk) {
        const seconds = Math.floor((Date.now() - afk.startedAt) / 1000);
        await message.reply({
          embeds: [embed(
            "💤 AFK",
            `<@${user.id}> şu anda AFK.\n` +
            `Sebep: **${afk.reason}**\n` +
            `Süre: **${seconds} saniye**`
          )]
        }).catch(() => {});
      }
    }
  } catch (e) {
    console.error("[ULTRA MESSAGE]", e);
  }
});

