async function registerUltraCommands() {
  try {
    const rest = new REST({ version: "10" }).setToken(TOKEN);

    const existing = await rest.get(
      Routes.applicationCommands(CLIENT_ID)
    ).catch(() => []);

    const merged = [
      ...commands.map(c => c.toJSON()),
      ...ultraCommands.map(c => c.toJSON())
    ];

    // Remove duplicate command names before registration.
    const unique = [];
    const seen = new Set();

    for (const command of merged) {
      if (seen.has(command.name)) continue;
      seen.add(command.name);
      unique.push(command);
    }

    await rest.put(
      Routes.applicationCommands(CLIENT_ID),
      { body: unique }
    );

    console.log(`✅ ${unique.length} slash komut kayıt edildi.`);
  } catch (e) {
    console.error("[ULTRA REGISTER]", e);
  }
}

client.once(Events.ClientReady, async () => {
  await registerUltraCommands();
  startUltraScheduler();

  for (const guild of client.guilds.cache.values()) {
    ultraGuild(guild.id);
  }

  ultraSave();
  console.log(`🚀 Ultra sistem ${ULTRA_VERSION} aktif.`);
});

/*
  Ultra interaction handler.
  It is separate from the original handler to keep this one-file build
  maintainable. All errors are contained.
*/
client.on(Events.InteractionCreate, async interaction => {
  try {
    if (!interaction.isChatInputCommand()) return;

    const name = interaction.commandName;
    if (!ultraCommands.some(c => c.name === name)) return;

    const guild = interaction.guild;
    if (!guild) return;

    const member = await guild.members.fetch(interaction.user.id).catch(() => null);
    if (!member) {
      return interaction.reply({
        content: "❌ Üye bilgisi alınamadı.",
        ephemeral: true
      });
    }

    if (name === "full-setup") {
      if (!ultraCan(member, "Administrator")) {
        return interaction.reply({
          content: "❌ Bu komut sadece yöneticiler içindir.",
          ephemeral: true
        });
      }

      await interaction.deferReply({ ephemeral: true });
      await ultraFullSetup(guild);
      return interaction.editReply(
        "🚀 **Ultra sunucu kurulumu tamamlandı.**\n" +
        "Roller, kategoriler, güvenlik altyapısı, izin matrisi ve log sistemi hazır."
      );
    }

    if (name === "sunucu-yenile") {
      if (!ultraCan(member, "Administrator")) {
        return interaction.reply({ content: "❌ Bu komut sadece Administrator yetkisi olanlar içindir.", ephemeral: true });
      }

      await interaction.deferReply({ ephemeral: true });
      const women = await syncServerFromScratch(guild);
      await ultraSendLog(
        guild,
        "SERVER_SYNC",
        "🔄 Sunucu Yapısı Yenilendi",
        `Yetkili: ${member}\nRoller, kanallar, güvenlik izinleri ve özel alanlar senkronize edildi.`
      );
      return interaction.editReply(
        "✅ **Sunucu entegrasyonu yenilendi.**\n" +
        "• Mevcut içerikler silinmedi\n" +
        "• Roller ve kanal izinleri senkronize edildi\n" +
        "• Güvenlik yapısı güncellendi\n" +
        `• 👩 Kadın rolü: <@&${women.role.id}>\n` +
        `• 👩 Özel kanal: <#${women.channel.id}>`
      );
    }

    if (name === "kadin-rol") {
      if (!ultraCan(member, "Administrator")) {
        return interaction.reply({ content: "❌ Bu komut sadece Administrator yetkisi olanlar içindir.", ephemeral: true });
      }

      const target = await guild.members.fetch(interaction.options.getUser("uye").id).catch(() => null);
      if (!target) return interaction.reply({ content: "❌ Üye bulunamadı.", ephemeral: true });
      if (target.user.bot) return interaction.reply({ content: "❌ Botlara bu rol verilemez.", ephemeral: true });

      const women = await ensureWomenArea(guild);
      const action = interaction.options.getString("islem");

      if (action === "ver") {
        if (target.roles.cache.has(women.role.id)) {
          return interaction.reply({ content: "ℹ️ Bu üyede kadınlara özel erişim rolü zaten var.", ephemeral: true });
        }
        if (!women.role.editable) {
          return interaction.reply({ content: "❌ Kadın rolü bot tarafından yönetilemiyor. Bot rolünü daha yukarı taşı.", ephemeral: true });
        }
        await target.roles.add(women.role, `Kadın özel alan erişimi — Yetkili: ${member.user.tag}`);
        await ultraSendLog(guild, "WOMEN_ROLE_GRANT", "👩 Özel Alan Rolü Verildi", `${target} ← ${member}`);
        return interaction.reply({ content: `✅ ${target} kullanıcısına <@&${women.role.id}> rolü verildi.`, ephemeral: true });
      }

      if (!target.roles.cache.has(women.role.id)) {
        return interaction.reply({ content: "ℹ️ Bu üyede kadınlara özel erişim rolü bulunmuyor.", ephemeral: true });
      }
      await target.roles.remove(women.role, `Kadın özel alan erişimi kaldırıldı — Yetkili: ${member.user.tag}`);
      await ultraSendLog(guild, "WOMEN_ROLE_REVOKE", "👩 Özel Alan Rolü Alındı", `${target} ← ${member}`);
      return interaction.reply({ content: `✅ ${target} kullanıcısından <@&${women.role.id}> rolü alındı.`, ephemeral: true });
    }

    if (name === "mod-merkezi") {
      if (!ultraStaff(member)) return interaction.reply({content:"❌ Moderasyon yetkin yok.",ephemeral:true});
      const list=ultraCases(guild.id).slice(-5).reverse();
      const recent=list.length ? list.map(x=>`#${x.id} • **${x.type}** • <@${x.targetId}>`).join("\n") : "Kayıt yok.";
      const row=new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId("v42_sync").setLabel("Rol Senkronize").setEmoji("🔄").setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId("v42_security").setLabel("Güvenlik").setEmoji("🛡️").setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId("v42_lock").setLabel("Lockdown").setEmoji("🔒").setStyle(ButtonStyle.Danger)
      );
      return interaction.reply({embeds:[embed("🛡️ v4.2 Moderasyon Merkezi",`**Üye:** ${guild.memberCount}\n**Toplam Case:** ${ultraCases(guild.id).length}\n\n**Son işlemler**\n${recent}`)],components:[row],ephemeral:true});
    }

    if (name === "mod-stats") {
      if (!ultraStaff(member)) return interaction.reply({content:"❌ Yetkin yok.",ephemeral:true});
      const cases=ultraCases(guild.id);
      const types=["WARN","BAN","KICK","TIMEOUT","PURGE","UNBAN","QUARANTINE"];
      const summary=types.map(t=>`**${t}:** ${cases.filter(x=>x.type===t).length}`).join("\n");
      return interaction.reply({embeds:[embed("📊 Moderasyon İstatistikleri",`${summary}\n\n**Toplam:** ${cases.length}`)],ephemeral:true});
    }

    if (name === "purge") {
      if (!ultraCan(member,"ManageMessages") && !ultraStaff(member)) return interaction.reply({content:"❌ Mesaj yönetme yetkin yok.",ephemeral:true});
      if (!interaction.channel?.bulkDelete) return interaction.reply({content:"❌ Bu kanalda kullanılamaz.",ephemeral:true});
      const amount=interaction.options.getInteger("miktar");
      await interaction.deferReply({ephemeral:true});
      const result=await interaction.channel.bulkDelete(amount,true);
      const item=nextCase(guild.id,"PURGE",interaction.user.id,interaction.user.id,`${result.size} mesaj temizlendi`);
      await ultraSendLog(guild,"PURGE",`🧹 Purge #${item.id}`,`Kanal: ${interaction.channel}\nYetkili: ${interaction.user}\nMesaj: ${result.size}`);
      return interaction.editReply(`✅ **${result.size}** mesaj temizlendi. Case #${item.id}`);
    }

    if (name === "unban-id") {
      if (!ultraCan(member,"BanMembers") && !ultraCan(member,"Administrator")) return interaction.reply({content:"❌ Ban yönetme yetkin yok.",ephemeral:true});
      const id=interaction.options.getString("userid").trim(), reason=interaction.options.getString("sebep")||"Unban";
      if (!/^\d{17,20}$/.test(id)) return interaction.reply({content:"❌ Geçerli bir Discord kullanıcı ID'si gir.",ephemeral:true});
      try {
        await guild.members.unban(id,reason);
        const item=nextCase(guild.id,"UNBAN",id,interaction.user.id,reason);
        await ultraSendLog(guild,"UNBAN",`♻️ Unban #${item.id}`,`ID: ${id}\nYetkili: ${interaction.user}\nSebep: ${reason}`);
        return interaction.reply({content:`✅ **${id}** ban listesinden çıkarıldı.`,ephemeral:true});
      } catch(e) { return interaction.reply({content:"❌ Kullanıcı banlı değil veya Discord işlemi reddetti.",ephemeral:true}); }
    }

    if (name === "yetki-ver") {
      if (!ultraCan(member,"Administrator")) return interaction.reply({content:"❌ Sadece yöneticiler yetki verebilir.",ephemeral:true});
      const target=await guild.members.fetch(interaction.options.getUser("uye").id).catch(()=>null);
      const profile=interaction.options.getString("profil");
      if (!target || target.id===guild.ownerId || target.id===member.id) return interaction.reply({content:"❌ Bu üyeye işlem uygulanamaz.",ephemeral:true});
      const roleId=guildData(guild.id).roles[profile], role=roleId&&guild.roles.cache.get(roleId);
      if (!role) return interaction.reply({content:"❌ Önce /full-setup çalıştır.",ephemeral:true});
      if (role.position>=member.roles.highest.position && member.id!==guild.ownerId) return interaction.reply({content:"❌ Rol hiyerarşisi izin vermiyor.",ephemeral:true});
      await target.roles.add(role,`v4.2 yetki profili: ${profile}`);
      const item=nextCase(guild.id,"ROLE_GRANT",target.id,member.id,`Profil: ${profile}`);
      await ultraSendLog(guild,"ROLE_GRANT",`🛡️ Yetki Verildi #${item.id}`,`${target} → ${profile}\nYetkili: ${member}`);
      return interaction.reply({content:`✅ ${target} → **${profile}**`,ephemeral:true});
    }

    if (name === "yetki-al") {
      if (!ultraCan(member,"Administrator")) return interaction.reply({content:"❌ Sadece yöneticiler.",ephemeral:true});
      const target=await guild.members.fetch(interaction.options.getUser("uye").id).catch(()=>null);
      if (!target || target.id===guild.ownerId || target.id===member.id) return interaction.reply({content:"❌ Bu üyeye işlem uygulanamaz.",ephemeral:true});
      const roles=guildData(guild.id).roles, ids=[roles.admin,roles.headMod,roles.mod,roles.trialMod,roles.support,roles.event].filter(Boolean);
      let removed=0; for(const id of ids) if(target.roles.cache.has(id)){await target.roles.remove(id,"v4.2 yetki kaldırma").catch(()=>{});removed++;}
      await ultraSendLog(guild,"ROLE_REVOKE","🧹 Yetkiler Kaldırıldı",`${target}\nYetkili: ${member}\nKaldırılan rol: ${removed}`);
      return interaction.reply({content:`✅ ${target} için **${removed}** personel rolü kaldırıldı.`,ephemeral:true});
    }

    if (name === "role-sync") {
      if (!ultraCan(member,"Administrator")) return interaction.reply({content:"❌ Sadece yöneticiler.",ephemeral:true});
      await interaction.deferReply({ephemeral:true});
      await setup(guild); await ultraBuildSecurityRoles(guild); await ultraSetupPermissionMatrix(guild);
      await ultraSendLog(guild,"ROLE_SYNC","🔄 Rol ve İzin Senkronizasyonu",`Yetkili: ${member}`);
      return interaction.editReply("✅ Roller, güvenlik rolleri ve kanal izinleri senkronize edildi.");
    }

    if (name === "automod-ayarla") {
      if (!ultraCan(member,"Administrator")) return interaction.reply({content:"❌ Sadece yöneticiler.",ephemeral:true});
      const cfg=guildData(guild.id); cfg.automod.enabled=true;
      cfg.automod.spam=interaction.options.getBoolean("spam");
      cfg.automod.links=interaction.options.getBoolean("link");
      ultraGuild(guild.id).moderation.antiCaps=interaction.options.getBoolean("caps");
      save(); ultraSave();
      await ultraSendLog(guild,"AUTOMOD","⚙️ AutoMod Güncellendi",`Spam: ${cfg.automod.spam}\nLink: ${cfg.automod.links}\nCaps: ${ultraGuild(guild.id).moderation.antiCaps}\nYetkili: ${member}`);
      return interaction.reply({content:"✅ AutoMod ayarları güncellendi.",ephemeral:true});
    }

    if (name === "case") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Yetkin yok.", ephemeral: true });
      }

      const id = interaction.options.getInteger("id");
      const item = ultraCases(guild.id).find(x => x.id === id);

      if (!item) {
        return interaction.reply({
          content: "❌ Case bulunamadı.",
          ephemeral: true
        });
      }

      return interaction.reply({
        embeds: [
          embed(
            `📁 Case #${item.id}`,
            `**Tür:** ${item.type}\n` +
            `**Hedef:** <@${item.targetId}>\n` +
            `**Yetkili:** <@${item.moderatorId}>\n` +
            `**Sebep:** ${item.reason}\n` +
            `**Tarih:** <t:${Math.floor(item.createdAt / 1000)}:F>`
          )
        ],
        ephemeral: true
      });
    }

    if (name === "cases") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Yetkin yok.", ephemeral: true });
      }

      const user = interaction.options.getUser("uye");
      const list = ultraCases(guild.id)
        .filter(x => x.targetId === user.id)
        .slice(-15)
        .reverse();

      return interaction.reply({
        embeds: [
          embed(
            `📁 ${user.tag} • Moderasyon Geçmişi`,
            list.length
              ? list.map(x =>
                  `**#${x.id} ${x.type}** • ${x.reason} • <t:${Math.floor(x.createdAt / 1000)}:R>`
                ).join("\n")
              : "Bu kullanıcı için kayıt yok."
          )
        ],
        ephemeral: true
      });
    }

    if (name === "afk") {
      const reason = interaction.options.getString("sebep") || "AFK";
      setAFK(guild.id, interaction.user.id, reason);

      return interaction.reply({
        embeds: [
          embed(
            "💤 AFK Aktif",
            `AFK sebebi: **${reason}**\nMentionlandığında bilgi verilecek.`
          )
        ]
      });
    }

    if (name === "remind") {
      const minutes = interaction.options.getInteger("dakika");
      const text = interaction.options.getString("mesaj");
      const item = addReminder(
        guild.id,
        interaction.user.id,
        interaction.channelId,
        text,
        Date.now() + minutes * 60_000
      );

      return interaction.reply({
        embeds: [
          embed(
            "⏰ Hatırlatıcı Oluşturuldu",
            `**${minutes} dakika** sonra hatırlatılacak.\n` +
            `ID: \`${item.id}\`\n${text}`
          )
        ],
        ephemeral: true
      });
    }

    if (name === "note-add") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Yetkin yok.", ephemeral: true });
      }

      const user = interaction.options.getUser("uye");
      const text = interaction.options.getString("not");
      const item = addNote(guild.id, user.id, interaction.user.id, text);

      await ultraSendLog(
        guild,
        "NOTE",
        `📝 Personel Notu #${item.id}`,
        `**Üye:** ${user}\n**Yetkili:** ${interaction.user}\n**Not:** ${text}`
      );

      return interaction.reply({
        content: `✅ ${user.tag} için personel notu eklendi.`,
        ephemeral: true
      });
    }

    if (name === "note-list") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Yetkin yok.", ephemeral: true });
      }

      const user = interaction.options.getUser("uye");
      const notes = getNotes(guild.id, user.id).slice(-20).reverse();

      return interaction.reply({
        embeds: [
          embed(
            `📝 ${user.tag} • Personel Notları`,
            notes.length
              ? notes.map(x =>
                  `**#${x.id}** <@${x.authorId}> • ${x.text} • <t:${Math.floor(x.createdAt / 1000)}:R>`
                ).join("\n")
              : "Not bulunmuyor."
          )
        ],
        ephemeral: true
      });
    }

    if (name === "suggest") {
      const text = interaction.options.getString("metin");
      const item = createSuggestion(guild.id, interaction.user.id, text);
      const cfg = ultraGuild(guild.id);

      const channel =
        (cfg.suggestions.channelId && guild.channels.cache.get(cfg.suggestions.channelId)) ||
        interaction.channel;

      const msg = await channel.send({
        embeds: [
          new EmbedBuilder()
            .setTitle(`💡 Öneri #${item.id}`)
            .setDescription(text)
            .addFields(
              { name: "Gönderen", value: `${interaction.user}`, inline: true },
              { name: "Durum", value: "🟡 Beklemede", inline: true },
              { name: "Oylar", value: "👍 0 • 👎 0", inline: true }
            )
            .setColor(0x5865F2)
            .setTimestamp()
        ]
      }).catch(() => null);

      if (msg) {
        await msg.react("👍").catch(() => {});
        await msg.react("👎").catch(() => {});
      }

      return interaction.reply({
        content: `✅ Önerin gönderildi. **#${item.id}**`,
        ephemeral: true
      });
    }

    if (name === "security") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Yetkin yok.", ephemeral: true });
      }

      const cfg = ultraGuild(guild.id).moderation;
      return interaction.reply({
        embeds: [
          embed(
            "🛡️ Güvenlik Ayarları",
            `**Sistem:** ${cfg.enabled ? "🟢 Açık" : "🔴 Kapalı"}\n` +
            `**Anti Invite:** ${cfg.antiInvite ? "🟢" : "🔴"}\n` +
            `**Anti Link:** ${cfg.antiLink ? "🟢" : "🔴"}\n` +
            `**Anti Caps:** ${cfg.antiCaps ? "🟢" : "🔴"}\n` +
            `**Anti Duplicate:** ${cfg.antiDuplicate ? "🟢" : "🔴"}\n` +
            `**Anti Mention Spam:** ${cfg.antiMentionSpam ? "🟢" : "🔴"}\n` +
            `**Mention limiti:** ${cfg.mentionLimit}\n` +
            `**Caps limiti:** %${cfg.capsPercent}`
          )
        ],
        ephemeral: true
      });
    }

    if (name === "security-toggle") {
      if (!ultraCan(member, "Administrator")) {
        return interaction.reply({ content: "❌ Sadece yönetici.", ephemeral: true });
      }

      const key = interaction.options.getString("ozellik");
      const value = interaction.options.getBoolean("durum");
      ultraGuild(guild.id).moderation[key] = value;
      ultraSave();

      await ultraSendLog(
        guild,
        "SECURITY",
        "🛡️ Güvenlik Ayarı Değişti",
        `**Özellik:** ${key}\n**Durum:** ${value ? "Açık" : "Kapalı"}\n**Yetkili:** ${interaction.user}`
      );

      return interaction.reply({
        content: `✅ \`${key}\` → **${value ? "Açık" : "Kapalı"}**`,
        ephemeral: true
      });
    }

    if (name === "backup") {
      if (!ultraCan(member, "Administrator")) {
        return interaction.reply({ content: "❌ Sadece yönetici.", ephemeral: true });
      }

      const file = saveGuildBackup(guild.id);
      return interaction.reply({
        content: "✅ Bot ayarlarının yedeği oluşturuldu.",
        files: [file],
        ephemeral: true
      });
    }

    if (name === "stats") {
      const stats = ultra.statistics[guild.id] || {};
      const members = guild.memberCount;
      const channels = guild.channels.cache.size;
      const roles = guild.roles.cache.size;

      return interaction.reply({
        embeds: [
          embed(
            "📊 Ultra Sunucu İstatistikleri",
            `👥 Üyeler: **${members}**\n` +
            `📁 Kanallar: **${channels}**\n` +
            `🎭 Roller: **${roles}**\n` +
            `🛡️ Güvenlik engelleri: **${stats.securityBlocks || 0}**\n` +
            `👋 Katılanlar: **${stats.joins || 0}**\n` +
            `🚪 Ayrılanlar: **${stats.leaves || 0}**\n` +
            `⚙️ Setup: **${ultraGuild(guild.id).fullSetupAt ? "Tamamlandı" : "Yapılmadı"}**`
          )
        ]
      });
    }

    if (name === "quarantine" || name === "unquarantine") {
      if (!ultraStaff(member)) {
        return interaction.reply({ content: "❌ Moderasyon yetkin yok.", ephemeral: true });
      }

      const user = interaction.options.getUser("uye");
      const target = await guild.members.fetch(user.id).catch(() => null);
      if (!target) {
        return interaction.reply({ content: "❌ Üye bulunamadı.", ephemeral: true });
      }

      if (target.id === guild.ownerId) {
        return interaction.reply({ content: "❌ Sunucu sahibi karantinaya alınamaz.", ephemeral: true });
      }

      const cfg = ultraGuild(guild.id);
      if (!cfg.quarantine.roleId) await ultraBuildSecurityRoles(guild);

      const role = guild.roles.cache.get(cfg.quarantine.roleId);
      if (!role) {
        return interaction.reply({ content: "❌ Karantina rolü bulunamadı.", ephemeral: true });
      }

      if (name === "quarantine") {
        const reason = interaction.options.getString("sebep") || "Karantina";
        await target.roles.add(role, reason).catch(() => {});
        const item = nextCase(guild.id, "QUARANTINE", target.id, member.id, reason);

        await ultraSendLog(
          guild,
          "QUARANTINE",
          `🚫 Karantina #${item.id}`,
          `${target} karantinaya alındı.\n**Yetkili:** ${member}\n**Sebep:** ${reason}`,
          0xED4245
        );

        return interaction.reply(`🚫 ${target} karantinaya alındı. Case #${item.id}`);
      }

      await target.roles.remove(role, "Karantina kaldırıldı").catch(() => {});
      await ultraSendLog(
        guild,
        "QUARANTINE",
        "✅ Karantina Kaldırıldı",
        `${target} karantinadan çıkarıldı.\n**Yetkili:** ${member}`,
        0x57F287
      );

      return interaction.reply(`✅ ${target} karantinadan çıkarıldı.`);
    }
  } catch (e) {
    console.error("[ULTRA INTERACTION]", e);
    if (interaction.replied || interaction.deferred) {
      await interaction.followUp({
        content: "❌ Ultra sisteminde beklenmeyen bir hata oluştu.",
        ephemeral: true
      }).catch(() => {});
    } else {
      await interaction.reply({
        content: "❌ Ultra sisteminde beklenmeyen bir hata oluştu.",
        ephemeral: true
      }).catch(() => {});
    }
  }
});

